'use client';

import { useMemo, useCallback, useState } from 'react';
import { useBuilderStore } from '@/hooks';
import { MarkdownViewer } from '../shared/MarkdownViewer';
import { useLocalization } from '@/context/LocalizationContext';
import { Card, CardContent } from '../ui/card';
import { Alert, AlertDescription } from '../ui/alert';
import { InfoIcon, FileTextIcon, LayoutIcon, Sparkles } from 'lucide-react';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Separator } from '../ui/separator';
import { cn } from '@/lib/utils/cn';

interface ReportResultsProps {
  activePanelKey: string | null;
}

/**
 * ReportResults Component - Improved UX
 * 
 * Enhanced with:
 * - Better visual hierarchy
 * - Improved empty states
 * - Better content organization
 * - Smooth transitions
 * - Enhanced accessibility
 * - Better mobile experience
 */
export default function ReportResults({ activePanelKey }: ReportResultsProps) {
  const { project } = useBuilderStore();
  const { t } = useLocalization();
  const [viewMode, setViewMode] = useState<'preview' | 'structure'>('preview');

  // Generate markdown from project
  const markdown = useMemo(() => {
    if (!project) return '';

    const parts: string[] = [];

    // Add cover page info
    if (project.name) {
      parts.push(`# ${project.name}\n`);
    }

    if (project.projectDescription) {
      parts.push(`${project.projectDescription}\n`);
    }

    // Add metadata
    const metadata: string[] = [];
    if (project.university) metadata.push(`**University:** ${project.university}`);
    if (project.supervisor) metadata.push(`**Supervisor:** ${project.supervisor}`);
    if (project.teamMembers?.length) {
      metadata.push(`**Team:** ${project.teamMembers.join(', ')}`);
    }

    if (metadata.length > 0) {
      parts.push(`\n${metadata.join('  \n')}\n`);
      parts.push('---\n');
    }

    // Add content from chapters and sections
    project.content.forEach((item, index) => {
      if ('sections' in item && Array.isArray(item.sections)) {
        // Chapter
        parts.push(`\n## ${index + 1}. ${item.title}\n`);
        item.sections.forEach((section, sIdx) => {
          parts.push(`\n### ${index + 1}.${sIdx + 1} ${section.title}\n`);
          if (section.content) {
            parts.push(`${section.content}\n`);
          } else {
            parts.push(`*No content generated yet.*\n`);
          }
        });
      } else if ('content' in item) {
        // Standalone section
        parts.push(`\n## ${item.title}\n`);
        if (item.content) {
          parts.push(`${item.content}\n`);
        } else {
          parts.push(`*No content generated yet.*\n`);
        }
      }
    });

    return parts.join('\n');
  }, [project]);

  // Calculate document statistics
  const stats = useMemo(() => {
    const wordCount = markdown.split(/\s+/).filter(w => w.length > 0).length;
    const charCount = markdown.length;
    const sectionCount = project?.content.reduce((acc, item) => {
      if ('sections' in item) return acc + item.sections.length;
      return acc + 1;
    }, 0) ?? 0;

    return { wordCount, charCount, sectionCount };
  }, [markdown, project]);

  const handleExportClick = useCallback(() => {
    // Scroll to export section in generator panel
    const exportSection = document.querySelector('[data-panel="export"]');
    if (exportSection) {
      exportSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  }, []);

  // Empty state when no project
  if (!project) {
    return (
      <div className="h-full flex items-center justify-center p-8">
        <Card className="max-w-md w-full border-dashed">
          <CardContent className="pt-6 text-center space-y-4">
            <div className="flex justify-center">
              <div className="h-16 w-16 rounded-full bg-primary/10 flex items-center justify-center">
                <FileTextIcon className="h-8 w-8 text-primary" />
              </div>
            </div>
            <div className="space-y-2">
              <h3 className="font-semibold text-lg">No Project Loaded</h3>
              <p className="text-sm text-muted-foreground">
                Create a new project or load an existing one to get started.
              </p>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  // Empty state when no content
  if (markdown.trim().length === 0 || project.content.length === 0) {
    return (
      <div className="h-full flex items-center justify-center p-8">
        <Card className="max-w-md w-full border-dashed">
          <CardContent className="pt-6 text-center space-y-4">
            <div className="flex justify-center">
              <div className="h-16 w-16 rounded-full bg-primary/10 flex items-center justify-center">
                <Sparkles className="h-8 w-8 text-primary animate-pulse" />
              </div>
            </div>
            <div className="space-y-2">
              <h3 className="font-semibold text-lg">Ready to Generate</h3>
              <p className="text-sm text-muted-foreground">
                Use the generator panel on the left to create your table of contents
                and start generating content.
              </p>
            </div>
            <Alert>
              <InfoIcon className="h-4 w-4" />
              <AlertDescription>
                <strong>Tip:</strong> Start by creating a table of contents or add chapters
                manually to structure your document.
              </AlertDescription>
            </Alert>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="h-full flex flex-col overflow-hidden">
      {/* Header with stats and actions */}
      <div className="flex-none border-b bg-muted/30 backdrop-blur-sm">
        <div className="p-4 space-y-3">
          {/* Title and view mode */}
          <div className="flex items-center justify-between gap-4">
            <div className="flex items-center gap-2">
              <LayoutIcon className="h-5 w-5 text-muted-foreground" />
              <h2 className="font-semibold text-lg">Document Preview</h2>
            </div>

            <div className="flex items-center gap-2">
              <Button
                variant={viewMode === 'preview' ? 'default' : 'outline'}
                size="sm"
                onClick={() => setViewMode('preview')}
              >
                Preview
              </Button>
              <Button
                variant={viewMode === 'structure' ? 'default' : 'outline'}
                size="sm"
                onClick={() => setViewMode('structure')}
              >
                Structure
              </Button>
            </div>
          </div>

          {/* Stats */}
          <div className="flex flex-wrap items-center gap-2 text-xs">
            <Badge variant="secondary" className="gap-1">
              <FileTextIcon className="h-3 w-3" />
              {stats.sectionCount} sections
            </Badge>
            <Badge variant="secondary">
              {stats.wordCount.toLocaleString()} words
            </Badge>
            <Badge variant="secondary">
              {stats.charCount.toLocaleString()} characters
            </Badge>
            <Separator orientation="vertical" className="h-4" />
            <Button
              variant="ghost"
              size="sm"
              onClick={handleExportClick}
              className="h-7 text-xs"
            >
              Export Options →
            </Button>
          </div>
        </div>
      </div>

      {/* Content area with better scrolling */}
      <div className="flex-1 overflow-hidden">
        {viewMode === 'preview' ? (
          <div className="h-full overflow-y-auto">
            <div className="p-6 sm:p-8 lg:p-10">
              <div className={cn(
                "mx-auto prose prose-sm sm:prose-base lg:prose-lg",
                "dark:prose-invert",
                "max-w-none lg:max-w-4xl",
                "animate-in fade-in duration-500"
              )}>
                <MarkdownViewer content={markdown} />
              </div>
            </div>
          </div>
        ) : (
          <div className="h-full overflow-y-auto p-6 sm:p-8">
            <div className="max-w-3xl mx-auto space-y-4 animate-in fade-in duration-500">
              <h3 className="font-semibold text-lg mb-4">Document Structure</h3>
              {project.content.map((item, index) => (
                <Card key={item.id}>
                  <CardContent className="pt-6">
                    <div className="space-y-3">
                      <div className="flex items-start justify-between">
                        <h4 className="font-semibold">
                          {index + 1}. {item.title}
                        </h4>
                        {'sections' in item && (
                          <Badge variant="outline">{item.sections.length} sections</Badge>
                        )}
                      </div>
                      {'sections' in item && item.sections.length > 0 && (
                        <ul className="ml-6 space-y-1 text-sm text-muted-foreground">
                          {item.sections.map((section, sIdx) => (
                            <li key={section.id}>
                              {index + 1}.{sIdx + 1} {section.title}
                              {section.content && (
                                <Badge variant="secondary" className="ml-2 text-xs">
                                  {section.content.split(/\s+/).length} words
                                </Badge>
                              )}
                            </li>
                          ))}
                        </ul>
                      )}
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
